8const int max_misses = 6;
9
10// Message class for displaying messages and design
11class Message {
12public:
13
14    // method to greet the player
15    void greet() {
16        cout << "------------------------------" << endl;
17        cout << "\t\tH A N G M A N" << endl;
18        cout << "------------------------------" << endl;
19        cout << "Guess the Word" << endl << endl;
20    }
21
22    // method to display the number of misses
23    void display_misses(int misses) {
24        cout << "Remaining misses: "<< max_misses - misses << endl << endl;
25    }
26
27    // method to display the incorrect guesses
28    void display_incorrect_guesses(string incorrect) {
29        cout << "Incorrect Guesses: " << incorrect << endl;
30    }
31    
32    // method to display the user answer
33    void display_user_answer(string user_answer) {
34        cout << "Your Answer: ";
35        for (char c: user_answer) {
36            cout << c << " ";
37        }
38
39        cout << endl;
40    }
41
42    // method to call when the user
43    // enters non-alphabetic character
44    void invalid_character_message() {
45        cout << "\nInvalid character!" << endl;
46        cout << "Input must be an alphabet!" << endl;
47    }
48
49    // method to call when the user enters a
50    // character that has already been entered
51    void already_entered_message() {
52        cout << "\nYou have already entered this letter!" << endl;
53        cout << "Enter another letter!" << endl;
54    }
55
56    void correct_message() {
57        cout << "\nCorrect!" << endl;
58    }
59
60    void incorrect_message() {
61        cout << "\nIncorrect!" << endl;
62    }
63
64    // print win or loss message
65    void final_result(string user_answer, string word) {
66        cout << "Your Answer: ";
67        for (char c: user_answer) {
68            cout << c << " ";
69        }
70
71        cout << endl << endl;
72
73        // print win message
74        if (user_answer == word) {
75            cout << "-----------------------------------------------" << endl;
76            cout << "\t\t\t\tY O U  W I N" << endl;
77            cout << "-----------------------------------------------" << endl;
78        }
79
80        // print loss message
81        else {
82            cout << "The correct answer is: " << word << endl << endl;
83            cout << "-----------------------------------------------" << endl;
84            cout << "\t\t\t\tY O U  L O S E" << endl;
85            cout << "-----------------------------------------------" << endl;
86        }
87    }
88};
