180int main() {
181
182
183    // create word database
184    string library[] = { 
185        "ALGORITHM", 
186        "AUTOPSY", 
187        "DATABASE", 
188        "UBIQUITOUS", 
189        "TANTALIZING", 
190        "REVELATION", 
191        "SPORADIC", 
192        "DISCRETE", 
193        "ANALYSIS", 
194        "CALCULUS" 
195    };
196
197    // generate random numbers between 0 and 9
198    srand(time(0));
199    int index = rand() % 10;
200
201    // choose the mystery word
202    // based on the random number
203    string chosen_word = library[index];
204
205
206    // variable to take user input
207    char letter;
208    
209    Message message;
210    Game game(chosen_word);
211
212    // greet the player
213    message.greet();
214
215    // play game until victory or loss
216    while (!game.is_game_over()) {
217
218        // display the game status
219        game.display_game_status();
220
221        cout << "\nPlease enter your guess: ";
222
223        // get user input and convert it to uppercase
224        cin >> letter;
225        letter = toupper(letter);
226
227        // check if input is an alphabet
228        if (game.is_guess_valid(letter)) {
229
230            // if input is valid, check if guess is correct
231            game.is_guess_correct(letter);
232        }
233    }
234
235    game.display_final_result();
236
237    return 0;
238}
